INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('C35', (SELECT id FROM categories WHERE code='C'), 'Verbod een voertuig links in te halen', 'No overtaking', 'Interdiction de dépasser', 'علامة ممنوع التجاوز', 'Verbod een voertuig links in te halen', 'No overtaking', 'Interdiction de dépasser', 'علامة ممنوع التجاوز', 'Dit verkeersbord verbiedt het inhalen van andere voertuigen op deze weg onder alle omstandigheden. Het wordt vaak gebruikt op plaatsen waar inhalen gevaarlijk is, zoals in bochten of op wegen met beperkt zicht.', 'This traffic sign prohibits overtaking other vehicles on this road under any circumstances. It is often used in places where overtaking is dangerous, such as in curves or on roads with limited visibility.', 'Ce panneau de signalisation interdit le dépassement d''autres véhicules sur cette route en toutes circonstances. Il est souvent utilisé dans les endroits où le dépassement est dangereux, comme dans les virages ou sur les routes à visibilité limitée.', 'تمنع هذه العلامة المرورية تجاوز المركبات الأخرى على هذا الطريق تحت أي ظرف من الظروف. يتم استخدامه غالبًا في الأماكن التي يكون فيها التجاوز خطيرًا، مثل المنحنيات أو على الطرق ذات الرؤية المحدودة.', '/api/traffic-signs/image/signs/prohibition_signs/C35 Verbod een voertuig links in te halen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

