INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D1f', (SELECT id FROM categories WHERE code='D'), 'Verplicht de aangeduide richting te volgen (rechtsaf)', 'Mandatory turn right', 'Obligation de tourner à droite', 'اتجه إلى اليمين بشكل إلزامي', 'Verplicht de aangeduide richting te volgen (rechtsaf)', 'Mandatory turn right', 'Obligation de tourner à droite', 'اتجه إلى اليمين بشكل إلزامي', 'Dit verkeersbord wordt geplaatst op smalle kruispunten of in speciale doorgangen zoals parkeerplaatsen of woongebieden. Het verplicht de bestuurder om naar rechts af te slaan en verbiedt rechtdoor of naar links te rijden.', 'This traffic sign is placed at narrow intersections or in special passages such as parking areas or residential areas. It requires the driver to turn right and prohibits driving straight ahead or to the left.', 'Ce panneau est placé aux carrefours étroits ou dans des passages spéciaux comme les aires de stationnement ou les zones résidentielles. Il oblige le conducteur à tourner à droite et interdit d''aller tout droit ou à gauche.', 'توضع هذه العلامة المرورية عند التقاطعات الضيقة أو في الممرات الخاصة مثل مواقف السيارات أو المناطق السكنية. يتطلب من السائق الانعطاف إلى اليمين ويمنع القيادة إلى الأمام أو إلى اليسار.', '/api/traffic-signs/image/signs/mandatory_signs/D1f Verplicht rechts afslaan.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D3a', (SELECT id FROM categories WHERE code='D'), 'Verplicht één van de pijlen te volgen (rechtdoor of linksaf)', 'Mandatory to follow one of the arrows (straight or left)', 'Obligation de suivre une des flèches (tout droit ou à gauche)', 'إجبارية اتباع أحد الاتجاهين (للأمام أو اليسار)', 'Verplicht één van de pijlen te volgen (rechtdoor of linksaf)', 'Mandatory to follow one of the arrows (straight or left)', 'Obligation de suivre une des flèches (tout droit ou à gauche)', 'إجبارية اتباع أحد الاتجاهين (للأمام أو اليسار)', 'Dit verkeersbord wordt geplaatst op kruispunten om bestuurders te verplichten rechtdoor te rijden of naar links af te slaan. Het is verboden om naar rechts af te slaan.', 'This traffic sign is placed at intersections to require drivers to go straight ahead or turn left. It prohibits turning right.', 'Ce panneau est placé aux carrefours pour obliger les conducteurs à aller tout droit ou à tourner à gauche. Il interdit de tourner à droite.', 'يتم وضع علامة المرور هذه عند التقاطعات لتطلب من السائقين المضي قدمًا بشكل مستقيم أو الانعطاف يسارًا. يمنع الانعطاف إلى اليمين.', '/api/traffic-signs/image/signs/mandatory_signs/D3a Verplicht één van de pijlen te volgen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D3b', (SELECT id FROM categories WHERE code='D'), 'Verplicht één van de pijlen te volgen (rechtdoor of rechtsaf)', 'Mandatory to follow one of the arrows (straight or right)', 'Obligation de suivre une des flèches (tout droit ou à droite)', 'إجبارية اتباع أحد الاتجاهين (للأمام أو اليمين)', 'Verplicht één van de pijlen te volgen (rechtdoor of rechtsaf)', 'Mandatory to follow one of the arrows (straight or right)', 'Obligation de suivre une des flèches (tout droit ou à droite)', 'إجبارية اتباع أحد الاتجاهين (للأمام أو اليمين)', 'Dit verkeersbord wordt geplaatst op kruispunten om bestuurders te verplichten rechtdoor te rijden of naar rechts af te slaan. Het is verboden om naar links af te slaan.', 'This traffic sign is placed at intersections to require drivers to go straight ahead or turn right. It prohibits turning left.', 'Ce panneau est placé aux carrefours pour obliger les conducteurs à aller tout droit ou à tourner à droite. Il interdit de tourner à gauche.', 'يتم وضع علامة المرور هذه عند التقاطعات لتطلب من السائقين المضي قدمًا بشكل مستقيم أو الانعطاف إلى اليمين. يمنع الانعطاف إلى اليسار.', '/api/traffic-signs/image/signs/mandatory_signs/D3b Verplicht één van de pijlen te volgen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D4-rechtdoor', (SELECT id FROM categories WHERE code='D'), 'Verplicht rechtdoor voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory straight ahead for vehicles carrying dangerous goods', 'Obligation d''aller tout droit pour les véhicules transportant des marchandises dangereuses', 'إلزامية السير للأمام مباشرة للمركبات التي تحمل بضائع خطرة', 'Verplicht rechtdoor voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory straight ahead for vehicles carrying dangerous goods', 'Obligation d''aller tout droit pour les véhicules transportant des marchandises dangereuses', 'إلزامية السير للأمام مباشرة للمركبات التي تحمل بضائع خطرة', 'Dit verkeersbord wordt geplaatst bij ingangen van gevoelige wegen zoals scholen of tunnels. Het verplicht bestuurders van voertuigen met gevaarlijke goederen om alleen rechtdoor te rijden zonder van richting te veranderen naar rechts of links.', 'This traffic sign is placed at entrances to sensitive roads such as schools or tunnels. It requires drivers of vehicles carrying dangerous goods to drive straight ahead only without changing direction to the right or left.', 'Ce panneau est placé aux entrées de routes sensibles comme les écoles ou les tunnels. Il oblige les conducteurs de véhicules transportant des marchandises dangereuses à rouler tout droit uniquement sans changer de direction vers la droite ou la gauche.', 'توضع هذه العلامة المرورية عند مداخل الطرق الحساسة مثل المدارس أو الأنفاق. يتطلب من سائقي المركبات التي تحمل بضائع خطرة القيادة للأمام فقط دون تغيير الاتجاه إلى اليمين أو اليسار.', '/api/traffic-signs/image/signs/mandatory_signs/D4 Verplicht rechtdoor gevaarlijke goederen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D4-links', (SELECT id FROM categories WHERE code='D'), 'Verplicht linksaf voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory left turn for vehicles carrying dangerous goods', 'Obligation de tourner à gauche pour les véhicules transportant des marchandises dangereuses', 'الانعطاف الإلزامي لليسار للمركبات التي تحمل بضائع خطرة', 'Verplicht linksaf voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory left turn for vehicles carrying dangerous goods', 'Obligation de tourner à gauche pour les véhicules transportant des marchandises dangereuses', 'الانعطاف الإلزامي لليسار للمركبات التي تحمل بضائع خطرة', 'Dit verkeersbord wordt geplaatst bij ingangen van gevoelige wegen zoals scholen of tunnels. Het verplicht bestuurders van voertuigen met gevaarlijke goederen om alleen naar links af te slaan, zonder rechtdoor te rijden of naar rechts af te slaan.', 'This traffic sign is placed at entrances to sensitive roads such as schools or tunnels. It requires drivers of vehicles carrying dangerous goods to turn left only, without driving straight ahead or turning right.', 'Ce panneau est placé aux entrées de routes sensibles comme les écoles ou les tunnels. Il oblige les conducteurs de véhicules transportant des marchandises dangereuses à tourner à gauche uniquement, sans aller tout droit ou tourner à droite.', 'توضع هذه العلامة المرورية عند مداخل الطرق الحساسة مثل المدارس أو الأنفاق. ويتطلب الأمر من سائقي المركبات التي تحمل بضائع خطرة الانعطاف إلى اليسار فقط، دون القيادة إلى الأمام مباشرة أو الانعطاف إلى اليمين.', '/api/traffic-signs/image/assets/signs/gebodsborden/D4 Verplicht links afslaan gevaarlijke goederen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D4-rechts', (SELECT id FROM categories WHERE code='D'), 'Verplicht rechts voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory right turn for vehicles carrying dangerous goods', 'Obligation de tourner à droite pour les véhicules transportant des marchandises dangereuses', 'الانعطاف إلى اليمين إلزامي للمركبات التي تحمل بضائع خطرة', 'Verplicht rechts voor voertuigen die gevaarlijke goederen vervoeren', 'Mandatory right turn for vehicles carrying dangerous goods', 'Obligation de tourner à droite pour les véhicules transportant des marchandises dangereuses', 'الانعطاف إلى اليمين إلزامي للمركبات التي تحمل بضائع خطرة', 'Dit verkeersbord wordt geplaatst bij ingangen van gevoelige wegen zoals scholen of tunnels. Het verplicht bestuurders van voertuigen met gevaarlijke goederen om alleen naar rechts af te slaan, zonder rechtdoor te rijden of naar links af te slaan.', 'This traffic sign is placed at entrances to sensitive roads such as schools or tunnels. It requires drivers of vehicles carrying dangerous goods to turn right only, without driving straight ahead or turning left.', 'Ce panneau est placé aux entrées de routes sensibles comme les écoles ou les tunnels. Il oblige les conducteurs de véhicules transportant des marchandises dangereuses à tourner à droite uniquement, sans aller tout droit ou tourner à gauche.', 'توضع هذه العلامة المرورية عند مداخل الطرق الحساسة مثل المدارس أو الأنفاق. ويتطلب الأمر من سائقي المركبات التي تحمل بضائع خطرة الانعطاف إلى اليمين فقط، دون القيادة إلى الأمام أو الانعطاف إلى اليسار.', '/api/traffic-signs/image/assets/signs/gebodsborden/D4 Verplicht rechts afslaan gevaarlijke goederen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('D11', (SELECT id FROM categories WHERE code='D'), 'Verplichte weg voor voetgangers', 'Mandatory path for pedestrians', 'Chemin obligatoire pour les piétons', 'مسار إجباري مخصص للمشاة', 'Verplichte weg voor voetgangers', 'Mandatory path for pedestrians', 'Chemin obligatoire pour les piétons', 'مسار إجباري مخصص للمشاة', 'Dit verkeersbord verplicht voetgangers om dit pad te gebruiken. Het wordt meestal geplaatst in woongebieden, parken of gebieden die zijn aangewezen voor voetgangers, en soms ook bij bouwplaatsen om het juiste pad aan te geven.', 'This traffic sign requires pedestrians to use this path. It is usually placed in residential areas, parks or areas designated for pedestrians, and sometimes also at construction sites to indicate the correct path.', 'Ce panneau oblige les piétons à utiliser ce chemin. Il est généralement placé dans les zones résidentielles, les parcs ou les zones réservées aux piétons, et parfois aussi sur les chantiers pour indiquer le chemin correct.', 'تتطلب إشارة المرور هذه من المشاة استخدام هذا المسار. يتم وضعها عادة في المناطق السكنية أو الحدائق أو المناطق المخصصة للمشاة، وأحياناً أيضاً في مواقع البناء للإشارة إلى المسار الصحيح.', '/api/traffic-signs/image/signs/mandatory_signs/D11 Verplichte weg voor voetgangers.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('C6', (SELECT id FROM categories WHERE code='C'), 'Verboden toegang voor quads', 'No entry for quads', 'Accès interdit aux quads', 'ممنوع دخول الدراجات الرباعية', 'Verboden toegang voor quads', 'No entry for quads', 'Accès interdit aux quads', 'ممنوع دخول الدراجات الرباعية', 'Dit bord verbiedt de toegang voor quads. Dit verbod is bedoeld om het milieu te beschermen of overlast te voorkomen in bepaalde gebieden zoals bossen of rustige wijken.', 'Quads are not allowed to enter from this point onwards. This prohibition aims to protect the environment or prevent disturbance in certain areas such as forests or quiet neighborhoods.', 'Les quads ne sont pas autorisés à entrer à partir de ce point. Cette interdiction vise à protéger l''environnement ou à éviter les nuisances dans certaines zones comme les forêts ou les quartiers calmes.', 'لا يُسمح للكواد بالدخول من هذه النقطة فصاعدًا. ويهدف هذا الحظر إلى حماية البيئة أو منع الإزعاج في مناطق معينة مثل الغابات أو الأحياء الهادئة.', '/api/traffic-signs/image/signs/prohibition_signs/C6 Verboden toegang voor bestuurders van quads.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F18', (SELECT id FROM categories WHERE code='F'), 'Rijstrook voorbehouden voor tram en bussen', 'Lane reserved for tram and buses', 'Voie réservée au tram et aux autobus', 'حارة مخصصة للترام والحافلات', 'Rijstrook voorbehouden voor tram en bussen', 'Lane reserved for tram and buses', 'Voie réservée au tram et aux autobus', 'حارة مخصصة للترام والحافلات', 'Dit bord geeft aan dat de rijstrook uitsluitend is voorbehouden voor bussen en trams. Deze strook bevindt zich vaak in het midden van de weg of langs de stoeprand. Andere voertuigen mogen deze strook niet gebruiken, behalve in uitzonderlijke gevallen zoals een tijdelijk obstakel op de weg (bijvoorbeeld een vrachtwagen die goederen lost).', 'This sign indicates that the lane is exclusively reserved for buses and trams. This lane is often located in the middle of the road or along the curb. Other vehicles may not use this lane, except in exceptional cases such as a temporary obstacle on the road (for example, a truck unloading goods).', 'Ce panneau indique que la voie est exclusivement réservée aux autobus et aux trams. Cette voie se trouve souvent au milieu de la route ou le long du trottoir. Les autres véhicules ne peuvent pas utiliser cette voie, sauf dans des cas exceptionnels comme un obstacle temporaire sur la route (par exemple, un camion déchargeant des marchandises).', 'تشير هذه الإشارة إلى أن المسار مخصص للحافلات والترام فقط. غالبًا ما يقع هذا المسار في منتصف الطريق أو على طول الرصيف. لا يجوز للمركبات الأخرى استخدام هذا المسار إلا في حالات استثنائية مثل وجود عائق مؤقت على الطريق (على سبيل المثال، شاحنة تقوم بتفريغ البضائع).', '/api/traffic-signs/image/signs/direction_signs/F18 Bijzondere overrijdbare bedding.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F17', (SELECT id FROM categories WHERE code='F'), 'Rijstrook voorbehouden voor bussen', 'Lane reserved for buses', 'Voie réservée aux autobus', 'حارة مخصصة للحافلات', 'Rijstrook voorbehouden voor bussen', 'Lane reserved for buses', 'Voie réservée aux autobus', 'حارة مخصصة للحافلات', 'Dit bord geeft aan dat de rijstrook uitsluitend is voorbehouden voor bussen. Andere voertuigen mogen deze strook alleen gebruiken bij uiterste noodzaak, zoals het inslaan van een zijweg of tijdelijk stoppen, niet voor doorlopend rijden.', 'This sign indicates that the lane is exclusively reserved for buses. Other vehicles may only use this lane when absolutely necessary, such as turning into a side road or temporary stopping, not for continuous driving.', 'Ce panneau indique que la voie est exclusivement réservée aux autobus. Les autres véhicules ne peuvent utiliser cette voie qu''en cas de nécessité absolue, comme pour tourner dans une route latérale ou un arrêt temporaire, pas pour une conduite continue.', 'تشير هذه الإشارة إلى أن المسار مخصص للحافلات فقط. لا يجوز للمركبات الأخرى استخدام هذا المسار إلا عند الضرورة القصوى، مثل الانعطاف إلى طريق جانبي أو التوقف المؤقت، وليس للقيادة المستمرة.', '/api/traffic-signs/image/signs/direction_signs/F17 Rijstrook aanduiding voorbehouden voor autobussen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F4b', (SELECT id FROM categories WHERE code='F'), 'Einde zone 30', 'End of 30 km/h zone', 'Fin de zone 30', 'نهاية منطقة سرعة 30 كم/س', 'Einde zone 30', 'End of 30 km/h zone', 'Fin de zone 30', 'نهاية منطقة سرعة 30 كم/س', 'Dit bord geeft het einde van een zone 30 aan. De maximumsnelheid van 30 km/u geldt niet meer vanaf dit punt. Vanaf hier mag u rijden volgens de snelheidslimieten die door andere borden worden aangegeven.', 'This sign indicates the end of a 30 km/h zone. The maximum speed of 30 km/h no longer applies from this point. From here, you may drive according to the speed limits indicated by other signs.', 'Ce panneau indique la fin d''une zone 30. La vitesse maximale de 30 km/h ne s''applique plus à partir de ce point. À partir d''ici, vous pouvez rouler selon les limites de vitesse indiquées par d''autres panneaux.', 'تشير هذه العلامة إلى نهاية منطقة السرعة 30 كم/ساعة. لم تعد السرعة القصوى البالغة 30 كم/ساعة سارية من هذه النقطة. من هنا يمكنك القيادة وفق حدود السرعة الموضحة بالعلامات الأخرى.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F4b Einde zone 30 kmu.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F4a', (SELECT id FROM categories WHERE code='F'), 'Begin zone 30', 'Start of 30 km/h zone', 'Début de zone 30', 'بداية منطقة سرعة 30 كم/س', 'Begin zone 30', 'Start of 30 km/h zone', 'Début de zone 30', 'بداية منطقة سرعة 30 كم/س', 'Dit bord geeft het begin van een zone 30 aan. In deze zone mag u niet sneller rijden dan 30 km/u. Deze zones worden vaak gebruikt in woonwijken om de verkeersveiligheid te verhogen.', 'This sign indicates the start of a 30 km/h zone. In this zone, you are not allowed to exceed 30 km/h. These zones are often used in residential areas to increase traffic safety.', 'Ce panneau indique le début d''une zone 30. Dans cette zone, vous ne pouvez pas dépasser 30 km/h. Ces zones sont souvent utilisées dans les quartiers résidentiels pour améliorer la sécurité routière.', 'تشير هذه العلامة إلى بداية منطقة بسرعة 30 كم/ساعة. في هذه المنطقة، لا يُسمح لك بتجاوز 30 كم/ساعة. غالبًا ما تستخدم هذه المناطق في المناطق السكنية لزيادة السلامة المرورية.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F4a Zone 30 km u.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F3a', (SELECT id FROM categories WHERE code='F'), 'Einde van een bebouwde kom', 'End of built-up area', 'Fin d''agglomération', 'علامة انتهاء المدينة', 'Einde van een bebouwde kom', 'End of built-up area', 'Fin d''agglomération', 'علامة انتهاء المدينة', 'Dit bord geeft aan dat je de bebouwde kom verlaat en dat je nu de hogere snelheden buiten de bebouwde kom mag volgen, tenzij er andere borden zijn die anders aangeven vanwege omstandigheden op de weg zoals een werkzone of onderhoud.', 'This sign indicates that you have left the built-up area, and you can now follow the higher speeds approved outside cities, unless there are other signs indicating otherwise due to road conditions such as a work zone or maintenance.', 'Ce panneau indique que vous avez quitté l''agglomération et que vous pouvez désormais suivre les vitesses plus élevées autorisées en dehors des villes, sauf si d''autres panneaux indiquent le contraire en raison des conditions routières comme une zone de travaux ou d''entretien.', 'تشير هذه العلامة إلى أنك غادرت المنطقة المبنية، ويمكنك الآن اتباع السرعات العالية المعتمدة خارج المدن، ما لم تكن هناك إشارات أخرى تشير إلى خلاف ذلك بسبب ظروف الطريق مثل منطقة العمل أو الصيانة.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F3a Einde van een bebouwde kom-2.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F1b', (SELECT id FROM categories WHERE code='F'), 'Begin van een bebouwde kom', 'Start of built-up area', 'Début d''agglomération', 'علامة دخول المدينة', 'Begin van een bebouwde kom', 'Start of built-up area', 'Début d''agglomération', 'علامة دخول المدينة', 'Dit bord geeft aan dat je een bebouwde kom binnenrijdt, wat betekent dat de stadsregels van toepassing worden vanaf dit bord, zoals de maximumsnelheid van 50 km/u of de aangegeven snelheid, en de algemene verkeersregels zoals voorrang en inhalen.', 'This sign indicates that you are entering a built-up area, which means that urban rules apply from this sign, such as the maximum speed of 50 km/h or the indicated speed, and general traffic rules such as priority and overtaking.', 'Ce panneau indique que vous entrez dans une agglomération, ce qui signifie que les règles urbaines s''appliquent à partir de ce panneau, comme la vitesse maximale de 50 km/h ou la vitesse indiquée, et les règles générales de circulation comme la priorité et le dépassement.', 'تشير هذه العلامة إلى أنك داخل منطقة مبنية، مما يعني أن القواعد الحضرية تنطبق من هذه العلامة، مثل السرعة القصوى 50 كم/ساعة أو السرعة المشار إليها، وقواعد المرور العامة مثل الأولوية والتجاوز.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F1b Begin van een bebouwde kom-2.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F1a', (SELECT id FROM categories WHERE code='F'), 'Begin van een bebouwde kom', 'Start of built-up area', 'Début d''une agglomération', 'علامة دخول المدينة', 'Begin van een bebouwde kom', 'Start of built-up area', 'Début d''une agglomération', 'علامة دخول المدينة', 'Dit bord geeft aan dat je een bebouwde kom binnengaat. Vanaf hier gelden de verkeersregels voor binnen de bebouwde kom, zoals een maximumsnelheid van 50 km/u, tenzij anders aangegeven.', 'This sign indicates that you are entering a built-up area (residential zone). From this point, urban traffic rules apply, such as a maximum speed limit of 50 km/h, unless otherwise indicated.', 'Ce panneau indique que vous entrez dans une agglomération (zone résidentielle). À partir de ce point, les règles de circulation urbaine s''appliquent, comme une limite de vitesse maximale de 50 km/h, sauf indication contraire.', 'تشير هذه العلامة إلى أنك تدخل منطقة مبنية (منطقة سكنية). ومن هذه النقطة، تنطبق قواعد المرور في المناطق الحضرية، مثل الحد الأقصى للسرعة وهو 50 كم/ساعة، ما لم تتم الإشارة إلى خلاف ذلك.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F1a Begin van een bebouwde kom-0.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F87', (SELECT id FROM categories WHERE code='F'), 'Verhoogde inrichting', 'Speed bump', 'Ralentisseur', 'مطب صناعي', 'Verhoogde inrichting', 'Speed bump', 'Ralentisseur', 'مطب صناعي', 'Dit bord geeft aan dat er een verkeersdrempel op de weg is om de snelheid te verminderen, vaak geplaatst bij scholen of woonwijken. Als het bord blauw is, is het alleen informatief, maar als het rood is, moet je de snelheid verlagen tot 30 km/u.', 'This sign indicates that there is a speed bump on the road to slow down traffic, often placed near schools or residential areas. If the sign is blue, it is informational only, but if it is red, you must reduce speed to 30 km/h.', 'Ce panneau indique qu''il y a un ralentisseur sur la route pour ralentir la circulation, souvent placé près des écoles ou des quartiers résidentiels. Si le panneau est bleu, il est uniquement informatif, mais s''il est rouge, vous devez réduire la vitesse à 30 km/h.', 'تشير هذه العلامة إلى وجود مطب للسرعة على الطريق لإبطاء حركة المرور، وغالباً ما يتم وضعه بالقرب من المدارس أو المناطق السكنية. إذا كانت الإشارة زرقاء، فهي للعلم فقط، أما إذا كانت حمراء، فيجب عليك خفض السرعة إلى 30 كم/ساعة.', '/api/traffic-signs/image/signs/direction_signs/F87 Verhoogde inrichting (vluchtheuvel).png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F45R', (SELECT id FROM categories WHERE code='F'), 'Doodlopende weg, rechtse doorgang', 'Dead end road with right exit', 'Voie sans issue avec sortie à droite', 'طريق مسدود مع المخرج الصحيح', 'Doodlopende weg, rechtse doorgang', 'Dead end road with right exit', 'Voie sans issue avec sortie à droite', 'طريق مسدود مع المخرج الصحيح', 'Dit bord geeft aan dat de huidige weg doodloopt, maar dat er aan het einde wel een doorgang naar rechts is. De weg biedt dus een alternatieve uitweg via rechts. Dit is vaak geschikt voor smalle gebieden.', 'This sign indicates that the current road is a dead end, but you can turn right at the end. This means the road offers an alternative exit to the right. This is often suitable for narrow areas.', 'Ce panneau indique que la route actuelle est sans issue, mais qu''il est possible de tourner à droite à la fin. La route offre donc une sortie alternative par la droite. Cela convient souvent aux zones étroites.', 'تشير هذه العلامة إلى أن الطريق الحالي هو طريق مسدود، ولكن يمكنك الانعطاف إلى اليمين في النهاية. وهذا يعني أن الطريق يوفر مخرجًا بديلاً إلى اليمين. غالبًا ما يكون هذا مناسبًا للمناطق الضيقة.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F45R Doodlopende weg, rechtse doorgang.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F45L', (SELECT id FROM categories WHERE code='F'), 'Doodlopende weg, linkse doorgang', 'Dead end road with left exit', 'Voie sans issue avec sortie à gauche', 'طريق مسدود مع مخرج يسار', 'Doodlopende weg, linkse doorgang', 'Dead end road with left exit', 'Voie sans issue avec sortie à gauche', 'طريق مسدود مع مخرج يسار', 'Dit bord geeft aan dat de huidige weg doodloopt, maar dat er aan het einde wel een doorgang naar links is. De weg biedt dus een alternatieve uitweg via links.', 'This sign indicates that the current road is a dead end, but you can turn left at the end. This means the road offers an alternative exit to the left.', 'Ce panneau indique que la route actuelle est sans issue, mais qu''il est possible de tourner à gauche à la fin. La route offre donc une sortie alternative par la gauche.', 'تشير هذه العلامة إلى أن الطريق الحالي هو طريق مسدود، ولكن يمكنك الانعطاف يسارًا في النهاية. وهذا يعني أن الطريق يوفر مخرجًا بديلاً إلى اليسار.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F45L Doodlopende weg, linkse doorgang.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F45b', (SELECT id FROM categories WHERE code='F'), 'Doodlopende weg, uitgezonderd voetgangers en fietsers', 'Dead end road, except for pedestrians and cyclists', 'Voie sans issue, sauf piétons et cyclistes', 'طريق مغلق باستثناء المشاة والدراجات', 'Doodlopende weg, uitgezonderd voetgangers en fietsers', 'Dead end road, except for pedestrians and cyclists', 'Voie sans issue, sauf piétons et cyclistes', 'طريق مغلق باستثناء المشاة والدراجات', 'Dit bord geeft aan dat de weg doodloopt voor voertuigen, maar wel doorgang biedt voor voetgangers en fietsers. Dit type bord wordt vaak gebruikt in woonwijken.', 'This sign indicates that the road is a dead end for vehicles, but remains open for pedestrians and cyclists. This type of sign is often used in residential areas.', 'Ce panneau indique que la route est sans issue pour les véhicules, mais reste ouverte aux piétons et cyclistes. Ce type de panneau est souvent utilisé dans les zones résidentielles.', 'تشير هذه الإشارة إلى أن الطريق هو طريق مسدود أمام المركبات، لكنه يبقى مفتوحاً أمام المشاة وراكبي الدراجات. غالبًا ما يستخدم هذا النوع من العلامات في المناطق السكنية.', '/api/traffic-signs/image/assets/signs/aanwijzingsborden/F45b Doodlopende weg, uitgezonderd voetgangers en fietsers.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GIa', (SELECT id FROM categories WHERE code='G'), 'Aanduiding van een afstand', 'Distance indication', 'Indication de distance', 'إشارة المسافة', 'Aanduiding van een afstand', 'Distance indication', 'Indication de distance', 'إشارة المسافة', 'Dit bord verduidelijkt de hoofdrichting van de weg of de juiste rijstrook binnen een kruispunt met meer dan één rijstrook. Het helpt bestuurders te weten welke rijstrook ze moeten volgen zonder verwarring, en meestal heeft de bestuurder op de hoofdrijstrook (de bredere rijstrook) voorrang.', 'This sign clarifies the main direction of the road or the correct lane within an intersection with more than one lane. It helps drivers know which lane to follow without confusion, and usually the driver on the main lane (the wider lane) has priority.', 'Ce panneau clarifie la direction principale de la route ou la bonne voie dans un carrefour à plusieurs voies. Il aide les conducteurs à savoir quelle voie suivre sans confusion, et généralement le conducteur sur la voie principale (la voie plus large) a la priorité.', 'توضح هذه الإشارة الاتجاه الرئيسي للطريق أو المسار الصحيح ضمن تقاطع يضم أكثر من مسار. فهو يساعد السائقين على معرفة المسار الذي يجب اتباعه دون ارتباك، وعادةً ما تكون الأولوية للسائق الموجود على المسار الرئيسي (المسار الأوسع).', '/api/traffic-signs/image/assets/signs/onderborden/GIa Aanduiding van een afstand.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

