VALUES ('GIII-ijzel', (SELECT id FROM categories WHERE code='G'), 'Opgepast kans op ijzel', 'Caution risk of ice', 'Attention risque de verglas', 'انتباه خطر الجليد', 'Opgepast kans op ijzel', 'Caution risk of ice', 'Attention risque de verglas', 'انتباه خطر الجليد', 'Opgepast kans op ijzel', 'Caution risk of ice', 'Attention risque de verglas', 'انتباه خطر الجليد', '/api/traffic-signs/image/assets/signs/onderborden/GIII Opgepast kans op ijzel.png', TRUE, NOW(), NOW())
