VALUES ('GIV', (SELECT id FROM categories WHERE code='G'), 'Enkel laden en lossen', 'Loading and unloading only', 'Chargement et déchargement uniquement', 'التحميل والتفريغ فقط', 'Enkel laden en lossen', 'Loading and unloading only', 'Chargement et déchargement uniquement', 'التحميل والتفريغ فقط', 'Enkel laden en lossen', 'Loading and unloading only', 'Chargement et déchargement uniquement', 'التحميل والتفريغ فقط', '/api/traffic-signs/image/assets/signs/onderborden/GIV Enkel laden & lossen.png', TRUE, NOW(), NOW())
