INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GV', (SELECT id FROM categories WHERE code='G'), 'Aanvulling op de verkeersborden stilstaan en parkeren', 'Supplement to stopping and parking signs', 'Complément aux panneaux d''arrêt et de stationnement', 'تكملة لعلامات التوقف والوقوف', 'Aanvulling op de verkeersborden stilstaan en parkeren', 'Supplement to stopping and parking signs', 'Complément aux panneaux d''arrêt et de stationnement', 'تكملة لعلامات التوقف والوقوف', 'Aanvulling op de verkeersborden stilstaan en parkeren', 'Supplement to stopping and parking signs', 'Complément aux panneaux d''arrêt et de stationnement', 'تكملة لعلامات التوقف والوقوف', '/api/traffic-signs/image/assets/signs/onderborden/GV Aanvulling op de verkeersborden stilstaan en parkeren.png', TRUE, NOW(), NOW())
