VALUES ('GIX', (SELECT id FROM categories WHERE code='G'), 'Versmalling van een rijstrook', 'Lane narrowing', 'Rétrécissement de voie', 'تضييق المسار', 'Versmalling van een rijstrook', 'Lane narrowing', 'Rétrécissement de voie', 'تضييق المسار', 'Versmalling van een rijstrook', 'Lane narrowing', 'Rétrécissement de voie', 'تضييق المسار', '/api/traffic-signs/image/assets/signs/onderborden/GIX Versmalling van een rijstrook.png', TRUE, NOW(), NOW())
