INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GXa', (SELECT id FROM categories WHERE code='G'), 'Begin van de reglementering', 'Start of regulation', 'Début de la réglementation', 'بداية تطبيق العلامة المرورية', 'Begin van de reglementering', 'Start of regulation', 'Début de la réglementation', 'بداية تطبيق العلامة المرورية', 'Dit bord geeft aan dat de toepassing van het verkeersbord vanaf deze plek begint, en bestuurders worden gevraagd zich aan de inhoud van dit bord te houden vanaf dit punt. Het wordt meestal geplaatst onder een parkeer- of stopverbodsbord.', 'This sign indicates that the application of the traffic sign starts from this specific place, and drivers are asked to comply with the content of this sign starting from this point. It is usually placed under a no parking or no stopping sign.', 'Ce panneau indique que l''application du panneau de signalisation commence à partir de cet endroit précis, et les conducteurs sont invités à respecter le contenu de ce panneau à partir de ce point. Il est généralement placé sous un panneau d''interdiction de stationner ou de s''arrêter.', 'وتشير هذه الإشارة إلى أن تطبيق العلامة المرورية يبدأ من هذا المكان المحدد، ويُطلب من السائقين الالتزام بمضمون هذه الإشارة بدءاً من هذا المكان. عادة ما يتم وضعها تحت علامة ممنوع الوقوف أو ممنوع التوقف.', '/api/traffic-signs/image/assets/signs/onderborden/GXa Begin van de reglementering.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GXb', (SELECT id FROM categories WHERE code='G'), 'Einde van de reglementering', 'End of regulation', 'Fin de la réglementation', 'نهاية تطبيق العلامة', 'Einde van de reglementering', 'End of regulation', 'Fin de la réglementation', 'نهاية تطبيق العلامة', 'Dit bord geeft aan dat het verkeersbord dat van kracht was, zijn toepassingsgebied heeft beëindigd vanaf dit punt, wat betekent dat bestuurders niet langer verplicht zijn zich te houden aan wat in het bovenstaande bord staat na het passeren van dit bord.', 'This sign indicates that the traffic sign that was in effect has ended its scope of application from this point, which means that drivers are no longer required to comply with what was stated in the sign above after passing this sign.', 'Ce panneau indique que le panneau de signalisation qui était en vigueur a terminé son champ d''application à partir de ce point, ce qui signifie que les conducteurs ne sont plus tenus de respecter ce qui était indiqué sur le panneau ci-dessus après avoir passé ce panneau.', 'تشير هذه الإشارة إلى أن العلامة المرورية التي كانت سارية المفعول قد انتهى نطاق تطبيقها من هذه النقطة، مما يعني أنه لم يعد مطلوباً من السائقين الالتزام بما ورد في الإشارة أعلاه بعد اجتياز هذه الإشارة.', '/api/traffic-signs/image/assets/signs/onderborden/GXb Einde van de reglementering.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GXc', (SELECT id FROM categories WHERE code='G'), 'Reglementering op een korte afstand', 'Regulation at a short distance', 'Réglementation à courte distance', 'التنظيم على مسافة قصيرة', 'Reglementering op een korte afstand', 'Regulation at a short distance', 'Réglementation à courte distance', 'التنظيم على مسافة قصيرة', 'Dit bord geeft aan dat de toepassing van het verkeersbord begint na een afstand van 20 meter vanaf de plaats waar dit bord is bevestigd, wat de bestuurder voldoende tijd geeft om zich voor te bereiden en te voldoen aan wat het bord voorschrijft. Het voorschrift moet worden nageleefd, anders krijgt u een verkeersboete.', 'This sign indicates that the application of the traffic sign starts after a distance of 20 meters from the place where this sign is installed, which gives the driver enough time to prepare and comply with what the sign prescribes. The regulation must be followed, otherwise you will receive a traffic fine.', 'Ce panneau indique que l''application du panneau de signalisation commence après une distance de 20 mètres à partir de l''endroit où ce panneau est installé, ce qui donne au conducteur suffisamment de temps pour se préparer et se conformer à ce que le panneau prescrit. Le règlement doit être respecté, sinon vous recevrez une amende de circulation.', 'تشير هذه الإشارة إلى أن تطبيق العلامة المرورية يبدأ بعد مسافة 20 متراً من مكان تركيب هذه الإشارة، مما يمنح السائق الوقت الكافي للاستعداد والالتزام بما تحدده الإشارة. يجب اتباع اللوائح، وإلا فسوف تتلقى غرامة مرورية.', '/api/traffic-signs/image/assets/signs/onderborden/GXc Reglementering op een korte afstand.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GXd', (SELECT id FROM categories WHERE code='G'), 'Reglementering op een lange afstand', 'Regulation over a long distance', 'Réglementation sur une longue distance', 'نطاق تطبيق العلامة المرورية', 'Reglementering op een lange afstand', 'Regulation over a long distance', 'Réglementation sur une longue distance', 'نطاق تطبيق العلامة المرورية', 'Dit bord geeft aan dat het betreffende verkeersbord van toepassing is binnen de afstand tussen het begin- en eindpunt, wat betekent dat bestuurders verplicht zijn de inhoud van het bord over deze gehele afstand na te leven.', 'This sign indicates that the traffic sign in question applies within the distance between the start and end points, meaning that drivers are required to apply the content of the sign throughout this entire distance.', 'Ce panneau indique que le panneau de signalisation concerné s''applique dans la distance entre les points de début et de fin, ce qui signifie que les conducteurs sont tenus d''appliquer le contenu du panneau sur toute cette distance.', 'تشير هذه الإشارة إلى أن العلامة المرورية المعنية تنطبق ضمن المسافة بين نقطتي البداية والنهاية، مما يعني أنه يتعين على السائقين تطبيق محتوى الإشارة طوال هذه المسافة بأكملها.', '/api/traffic-signs/image/assets/signs/onderborden/GXd Reglementering op een lange afstand.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('GXI', (SELECT id FROM categories WHERE code='G'), 'Afrit rechts', 'Exit on the right', 'Sortie à droite', 'علامة مخرج الطريق من اليمين', 'Afrit rechts', 'Exit on the right', 'Sortie à droite', 'علامة مخرج الطريق من اليمين', 'Dit bord geeft aan dat er een afrit in de buurt is aan de rechterkant van de weg, die vaak leidt naar het verlaten van de snelweg en het betreden van de volgende stad of regio. Dit bord helpt bestuurders de juiste route te nemen om veilig en soepel de weg te verlaten.', 'This sign indicates that there is an exit nearby on the right side of the road, which often leads to leaving the highway and entering the next city or area. This sign helps drivers take the correct route to exit the road safely and smoothly.', 'Ce panneau indique qu''il y a une sortie proche sur le côté droit de la route, qui mène souvent à quitter l''autoroute et à entrer dans la prochaine ville ou zone. Ce panneau aide les conducteurs à prendre la bonne route pour sortir de la route en toute sécurité et en douceur.', 'تشير هذه العلامة إلى وجود مخرج قريب على الجهة اليمنى من الطريق، والذي قد يؤدي غالبًا إلى الخروج من الطريق السريع والدخول إلى المدينة أو المنطقة القادمة. وتساعد هذه العلامة السائقين على اتخاذ المسار الصحيح للخروج من الطريق بشكل آمن وسلس.', '/api/traffic-signs/image/assets/signs/onderborden/GXI Afrit.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('M1', (SELECT id FROM categories WHERE code='G'), 'Enkel voor fietsers', 'Cyclists only', 'Cyclistes uniquement', 'راكبي الدراجات فقط', 'Enkel voor fietsers', 'Cyclists only', 'Cyclistes uniquement', 'راكبي الدراجات فقط', 'Dit bord verduidelijkt dat de weg of het pad exclusief is gereserveerd voor fietsen, en het is verboden voor andere voertuigen inclusief motorfietsen, en het recht op veilig verkeer moet worden gerespecteerd.', 'This sign clarifies that the road or path is reserved exclusively for bicycles, and it is prohibited for other vehicles including motorcycles, and the right to safe traffic must be respected.', 'Ce panneau clarifie que la route ou le chemin est réservé exclusivement aux vélos, et il est interdit aux autres véhicules y compris les motos, et le droit à la circulation sécuritaire doit être respecté.', 'توضح هذه الإشارة أن الطريق أو المسار مخصص للدراجات الهوائية حصراً، ويمنع دخول المركبات الأخرى بما في ذلك الدراجات النارية، ويجب احترام الحق في المرور الآمن.', '/api/traffic-signs/image/assets/signs/onderborden/M1 Enkel voor fietsers.png', TRUE, NOW(), NOW())
