VALUES ('M5', (SELECT id FROM categories WHERE code='G'), 'Fietsers en bromfietsers Klasse A mogen in 2 richtingen', 'Cyclists and moped class A may travel in both directions', 'Cyclistes et cyclomoteurs classe A dans les deux sens', 'يجوز لراكبي الدراجات والدراجات البخارية الصغيرة من الدرجة A السفر في كلا الاتجاهين', 'Fietsers en bromfietsers Klasse A mogen in 2 richtingen', 'Cyclists and moped class A may travel in both directions', 'Cyclistes et cyclomoteurs classe A dans les deux sens', 'يجوز لراكبي الدراجات والدراجات البخارية الصغيرة من الدرجة A السفر في كلا الاتجاهين', 'Dit bord verduidelijkt dat het verkeerspad bestemd is voor fietsen en lichte motorfietsen klasse A en dat verkeer in beide richtingen is toegestaan, wat extra voorzichtigheid vereist bij het inhalen of afslaan.', 'This sign clarifies that the traffic lane is designated for bicycles and light motorcycles class A and that traffic in both directions is allowed, which requires extra caution when overtaking or turning.', 'Ce panneau clarifie que la voie de circulation est destinée aux vélos et aux motos légères de classe A et que la circulation dans les deux sens est autorisée, ce qui nécessite une prudence supplémentaire lors du dépassement ou du virage.', 'توضح هذه الشاخصة أن المسار مخصص للدراجات الهوائية والدراجات النارية الخفيفة فئة (أ) وأن الحركة مسموحة في الاتجاهين مما يتطلب الحذر الشديد عند التجاوز أو الانعطاف.', '/api/traffic-signs/image/assets/signs/onderborden/M5 Fietsers en bromfietsers Klasse A mogen in 2 richtingen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

