VALUES ('M15', (SELECT id FROM categories WHERE code='G'), 'Verbod voor speed pedelecs', 'Speed pedelecs prohibited', 'Speed pedelecs interdits', 'ممنوع للدراجات الكهربائية السريعة', 'Verbod voor speed pedelecs', 'Speed pedelecs prohibited', 'Speed pedelecs interdits', 'ممنوع للدراجات الكهربائية السريعة', 'Verbod voor speed pedelecs', 'Speed pedelecs prohibited', 'Speed pedelecs interdits', 'ممنوع للدراجات الكهربائية السريعة', '/api/traffic-signs/image/assets/signs/onderborden/M15 Verbod voor speed pedelecs.png', TRUE, NOW(), NOW())
