VALUES ('M17', (SELECT id FROM categories WHERE code='G'), 'Fietsers en speed pedelecs mogen in 2 richtingen', 'Cyclists and speed pedelecs may travel in both directions', 'Cyclistes et speed pedelecs dans les deux sens', 'طريق مزدوج للدراجات الهوائية والسكوتر', 'Fietsers en speed pedelecs mogen in 2 richtingen', 'Cyclists and speed pedelecs may travel in both directions', 'Cyclistes et speed pedelecs dans les deux sens', 'طريق مزدوج للدراجات الهوائية والسكوتر', 'Dit bord geeft aan dat er een pad is voor fietsen en lichte motorfietsen (scooters) in beide richtingen. Alle andere weggebruikers moeten de voorrang van fietsen op dit pad respecteren.', 'This sign indicates that there is a path for bicycles and light motorcycles (scooters) in both directions. All other road users must respect the priority of bicycles on this path.', 'Ce panneau indique qu''il y a une voie pour les vélos et les motos légères (scooters) dans les deux sens. Tous les autres usagers de la route doivent respecter la priorité des vélos sur cette voie.', 'تشير هذه الإشارة إلى وجود مسار للدراجات الهوائية والدراجات النارية الخفيفة (السكوتر) في كلا الإتجاهين. يجب على جميع مستخدمي الطريق الآخرين احترام أولوية الدراجات على هذا المسار.', '/api/traffic-signs/image/assets/signs/onderborden/M17 Fietsers en speed pedelecs mogen in 2 richtingen.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('B23', (SELECT id FROM categories WHERE code='B'), 'Fietsers en speed pedelecs mogen rechtdoor rijden en de verkeerslichten voorbijrijden', 'Cyclists and speed pedelecs may go straight and pass traffic lights', 'Les cyclistes et speed pedelecs peuvent aller tout droit et passer les feux', 'تقاطع مع ممر الدراجات - الاتجاه للأمام', 'Fietsers en speed pedelecs mogen rechtdoor rijden en de verkeerslichten voorbijrijden', 'Cyclists and speed pedelecs may go straight and pass traffic lights', 'Les cyclistes et speed pedelecs peuvent aller tout droit et passer les feux', 'تقاطع مع ممر الدراجات - الاتجاه للأمام', 'Deze verkeersbord wordt geplaatst bij kruispunten waar een fietspad aanwezig is. Fietsers mogen rechtsaf slaan zelfs wanneer het verkeerslicht rood is, op voorwaarde dat ze voorrang geven aan andere weggebruikers (zoals auto''s en voetgangers) op de hoofdweg.', 'This sign is placed at intersections with a bicycle path. Cyclists may turn right even when the traffic light is red, provided they give priority to other road users (such as cars and pedestrians) on the main road.', 'Ce panneau est placé aux carrefours avec une piste cyclable. Les cyclistes peuvent tourner à droite même lorsque le feu est rouge, à condition de céder le passage aux autres usagers de la route (comme les voitures et les piétons) sur la route principale.', 'يتم وضع هذه العلامة عند التقاطعات مع مسار الدراجات. يجوز لراكبي الدراجات الانعطاف إلى اليمين حتى عندما تكون إشارة المرور حمراء، بشرط إعطاء الأولوية لمستخدمي الطريق الآخرين (مثل السيارات والمشاة) على الطريق الرئيسي.', 'images/signs/priority_signs/B23 Fietsers en speed pedelecs mogen rechtdoor rijden en de verkeerslichten voorbijrijden.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('M3bis', (SELECT id FROM categories WHERE code='G'), 'Uitgezonderd fietsers en bromfietsers', 'Except cyclists and moped riders', 'Sauf cyclistes et cyclomotoristes', 'باستثناء راكبي الدراجات والدراجات البخارية', 'Uitgezonderd fietsers en bromfietsers', 'Except cyclists and moped riders', 'Sauf cyclistes et cyclomotoristes', 'باستثناء راكبي الدراجات والدراجات البخارية', 'Dit bord betekent dat het verbod of de beperking aangegeven op het hoofdbord (zoals verboden toegang) niet van toepassing is op fietsen en lichte motorfietsen klasse A en B, en dat zij mogen passeren.', 'This sign means that the prohibition or restriction shown on the main sign (such as no entry) does not apply to bicycles and light motorcycles class A and B, and they are allowed to pass.', 'Ce panneau signifie que l''interdiction ou la restriction indiquée sur le panneau principal (comme l''accès interdit) ne s''applique pas aux vélos et aux motos légères de classe A et B, et ils sont autorisés à passer.', 'هذه الإشارة تعني أن المنع أو القيد الموضح في الإشارة الرئيسية (مثل ممنوع الدخول) لا ينطبق على الدراجات الهوائية والدراجات النارية الخفيفة من الصنف A وB، ويُسمح لها بالمرور.', '/api/traffic-signs/image/assets/signs/onderborden/M3bis Uitgezonderd fietsers en bromfietsers.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('ZC21-zone', (SELECT id FROM categories WHERE code='Z'), 'Einde zone verboden toegang voertuigen +3,5t', 'End of zone no entry for vehicles over 3.5t', 'Fin de zone d''accès interdit aux véhicules de plus de 3,5t', 'نهاية منطقة منع دخول المركبات التي يتجاوز وزنها 3.5 طن', 'Einde zone verboden toegang voertuigen +3,5t', 'End of zone no entry for vehicles over 3.5t', 'Fin de zone d''accès interdit aux véhicules de plus de 3,5t', 'نهاية منطقة منع دخول المركبات التي يتجاوز وزنها 3.5 طن', 'Dit bord geeft het einde aan van de zone waar voertuigen met een toegestane maximummassa van meer dan 3,5 ton niet mochten rijden. Vanaf dit punt gelden de gewichtsbeperkingen van deze zone niet meer, en zijn de algemene verkeersregels van toepassing volgens de verkeersborden en andere wegmarkeringen ter plaatse.', 'This traffic sign indicates the end of the zone where vehicles with an authorized maximum mass exceeding 3.5 tons were not allowed to enter. From this point onwards, the weight restrictions of this zone end, and general traffic rules apply according to the road signs and other traffic markings in place.', 'Ce panneau de signalisation indique la fin de la zone où les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes n''étaient pas autorisés à entrer. À partir de ce point, les restrictions de poids de cette zone prennent fin, et les règles générales de circulation s''appliquent selon les panneaux de signalisation et autres marquages routiers en place.', 'تشير إشارة المرور هذه إلى نهاية المنطقة التي لا يُسمح فيها بدخول المركبات التي يزيد وزنها الأقصى المسموح به عن 3.5 طن. ومن الآن فصاعدا، تنتهي قيود الوزن في هذه المنطقة، وتطبق قواعد المرور العامة وفقا لعلامات الطريق وعلامات المرور الأخرى الموجودة.', '/api/traffic-signs/image/assets/signs/zoneborden/ZC21 - Zone verboden toegang voor bestuurders van voertuigen waarvan de massa hoger is dan de aangeduide massa.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('ZE9a-v3', (SELECT id FROM categories WHERE code='Z'), 'Einde zone parkeren uitsluitend voor auto''s', 'End of zone parking exclusively for cars', 'Fin de zone stationnement réservé aux voitures', 'نهاية المنطقة لوقوف السيارات حصرا', 'Einde zone parkeren uitsluitend voor auto''s', 'End of zone parking exclusively for cars', 'Fin de zone stationnement réservé aux voitures', 'نهاية المنطقة لوقوف السيارات حصرا', 'Dit bord geeft het einde aan van de zone waar parkeren alleen voor auto''s was toegestaan. Vanaf dit punt geldt deze specifieke regel niet meer, en zijn de algemene parkeerregels van toepassing volgens de verkeersborden en andere wegmarkeringen ter plaatse.', 'This traffic sign indicates the end of the zone where parking was allowed exclusively for cars. From this point onwards, this specific rule ends, and general parking rules apply according to the road signs and other traffic markings in place.', 'Ce panneau de signalisation indique la fin de la zone où le stationnement était réservé exclusivement aux voitures. À partir de ce point, cette règle spécifique prend fin, et les règles générales de stationnement s''appliquent selon les panneaux de signalisation et autres marquages routiers en place.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي سمح فيها بوقوف السيارات حصراً. ومن الآن فصاعدا تنتهي هذه القاعدة المحددة، وتطبق القواعد العامة لوقوف السيارات وفقا لعلامات الطريق وعلامات المرور الأخرى الموجودة.', '/api/traffic-signs/image/assets/signs/zoneborden/ZE9a Zone parkeren uitsluitend voor auto''s_0.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-V', (SELECT id FROM categories WHERE code='M'), 'Type V - Bebakening van een bocht', 'Type V - Sharp curve delineation to the right', 'Type V - Balisage de virage serré à droite', 'النوع V - رسم منحنى حاد إلى اليمين', 'Type V - Bebakening van een bocht', 'Type V - Sharp curve delineation to the right', 'Type V - Balisage de virage serré à droite', 'النوع V - رسم منحنى حاد إلى اليمين', 'Dit bord wijst op een scherpe bocht naar rechts. Het wordt gebruikt om de richting van de weg te bevestigen op gevaarlijke of onduidelijke plekken. Bij het zien van dit bord moet u afremmen, goed opletten en de richting van de pijl nauwkeurig volgen om te voorkomen dat u van de weg raakt of een botsing veroorzaakt.', 'This traffic sign indicates a sharp curve heading to the right. It is used to confirm the direction of the road in dangerous or unclear locations. When seeing this sign, you must slow down, pay close attention, and follow the direction of the arrow precisely to avoid going off the road or causing a collision.', 'Ce panneau de signalisation indique un virage serré vers la droite. Il est utilisé pour confirmer la direction de la route dans les endroits dangereux ou peu clairs. En voyant ce panneau, vous devez ralentir, faire très attention et suivre la direction de la flèche avec précision pour éviter de quitter la route ou de provoquer une collision.', 'تشير إشارة المرور هذه إلى منحنى حاد يتجه إلى اليمين. يتم استخدامه لتأكيد اتجاه الطريق في الأماكن الخطرة أو غير الواضحة. عند رؤية هذه العلامة يجب عليك التهدئة والانتباه الشديد واتباع اتجاه السهم بدقة لتجنب الخروج عن الطريق أو التسبب في الاصطدام.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type V Bebakening van een bocht.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IC', (SELECT id FROM categories WHERE code='M'), 'Type Ic - Bebakening van een bocht', 'Type Ic - Curve delineation with vertical chevron arrows', 'Type Ic - Balisage de virage avec flèches verticales', 'النوع Ic - تحديد المنحنى باستخدام أسهم شيفرون عمودية', 'Type Ic - Bebakening van een bocht', 'Type Ic - Curve delineation with vertical chevron arrows', 'Type Ic - Balisage de virage avec flèches verticales', 'النوع Ic - تحديد المنحنى باستخدام أسهم شيفرون عمودية', 'Dit bord wijst op een gevaarlijke bocht of scherpe wijziging in de wegrichting, waarbij de verticaal opeenvolgende pijlen worden gebruikt om de bestuurder duidelijk te begeleiden langs de bocht. Het wordt vaak geplaatst bij lange of zeer scherpe bochten, en helpt om het juiste pad stap voor stap te volgen. Bij het zien van dit bord moet u afremmen, goed opletten en de richting van de pijlen nauwkeurig volgen om te voorkomen dat u van de weg raakt.', 'This traffic sign indicates a dangerous curve or sharp change in road direction, where the vertically consecutive arrows are used to clearly guide the driver along the curve. It is often placed at long or very sharp curves, and helps to follow the correct path step by step. When seeing this sign, you must slow down, pay close attention, and follow the direction of the arrows precisely to avoid going off the road.', 'Ce panneau de signalisation indique un virage dangereux ou un changement brusque de direction de la route, où les flèches consécutives verticales sont utilisées pour guider clairement le conducteur le long du virage. Il est souvent placé dans les virages longs ou très serrés, et aide à suivre le bon chemin étape par étape. En voyant ce panneau, vous devez ralentir, faire très attention et suivre la direction des flèches avec précision pour éviter de quitter la route.', 'تشير هذه العلامة المرورية إلى منحنى خطير أو تغيير حاد في اتجاه الطريق، حيث يتم استخدام الأسهم المتتالية عمودياً لتوجيه السائق بشكل واضح على طول المنحنى. وغالباً ما يتم وضعه على منحنيات طويلة أو حادة جداً، ويساعد على اتباع المسار الصحيح خطوة بخطوة. عند رؤية هذه العلامة يجب عليك التهدئة والانتباه الشديد واتباع اتجاه الأسهم بدقة لتجنب الخروج عن الطريق.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type Ic Bebakening van een bocht.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-VA', (SELECT id FROM categories WHERE code='M'), 'Type Va - Bebakening van een bocht', 'Type Va - Curve delineation with chevron arrows', 'Type Va - Balisage de virage avec flèches directionnelles', 'النوع Va - تحديد المنحنى بأسهم شيفرون', 'Type Va - Bebakening van een bocht', 'Type Va - Curve delineation with chevron arrows', 'Type Va - Balisage de virage avec flèches directionnelles', 'النوع Va - تحديد المنحنى بأسهم شيفرون', 'Dit bord wijst op een duidelijke of scherpe bocht in de richting van de weg, waarbij de opeenvolgende pijlen het pad aangeven dat de bestuurder moet volgen. Het wordt vaak gebruikt bij gevaarlijke bochten of op plaatsen waar de richting van de weg moeilijk te onderscheiden is. Bij het zien van dit bord moet u afremmen, opletten en de richting van de pijlen nauwkeurig volgen om te voorkomen dat u van de weg raakt.', 'This traffic sign indicates a clear or sharp curve in the direction of the road, where the consecutive arrows show the path that the driver must follow. It is often used at dangerous curves or places where the direction of the road is difficult to distinguish. When seeing this sign, you must slow down, pay attention, and follow the direction of the arrows precisely to avoid going off the road.', 'Ce panneau de signalisation indique un virage clair ou serré dans la direction de la route, où les flèches consécutives montrent le chemin que le conducteur doit suivre. Il est souvent utilisé dans les virages dangereux ou les endroits où la direction de la route est difficile à distinguer. En voyant ce panneau, vous devez ralentir, faire attention et suivre la direction des flèches avec précision pour éviter de quitter la route.', 'تشير هذه العلامة المرورية إلى منحنى واضح أو حاد في اتجاه الطريق، حيث توضح الأسهم المتتالية المسار الذي يجب على السائق اتباعه. وغالبا ما يستخدم عند المنحنيات الخطرة أو الأماكن التي يصعب فيها تمييز اتجاه الطريق. عند رؤية هذه الإشارة يجب عليك التهدئة والانتباه واتباع اتجاه الأسهم بدقة لتجنب الخروج عن الطريق.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type VaBebakening van een bocht.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('MARK-R3', (SELECT id FROM categories WHERE code='M'), 'Markering rechts verticaal type 3', 'Vertical lateral guidance marker', 'Balise de guidage latéral verticale', 'علامة التوجيه الجانبي العمودي', 'Markering rechts verticaal type 3', 'Vertical lateral guidance marker', 'Balise de guidage latéral verticale', 'علامة التوجيه الجانبي العمودي', 'Dit bord wijst op een obstakel of wegrand waarop gelet moet worden, en wordt gebruikt om de bestuurder visueel te begeleiden langs het pad, vooral bij wegversmallingen of wegwerkzaamheden. De richting van de schuine lijnen geeft de veilige kant van doorgang aan, en u moet langs dit bord rijden terwijl u afremt en oplet om een botsing te voorkomen.', 'This sign indicates an obstacle or road edge that requires attention, and is used to visually guide the driver along the path, especially at narrowings or roadworks. The direction of the diagonal lines indicates the safe side of passage, and you must drive alongside it while slowing down and paying attention to avoid a collision.', 'Ce panneau indique un obstacle ou un bord de route qui nécessite une attention particulière, et est utilisé pour guider visuellement le conducteur le long du trajet, notamment lors de rétrécissements ou de travaux routiers. La direction des lignes diagonales indique le côté sûr de passage, et vous devez rouler le long de ce panneau en ralentissant et en faisant attention pour éviter une collision.', 'تشير هذه العلامة إلى وجود عائق أو حافة طريق تتطلب الانتباه، وتستخدم لتوجيه السائق بصريًا على طول المسار، خاصة عند التضييقات أو أعمال الطرق. يشير اتجاه الخطوط القطرية إلى الجانب الآمن للمرور، ويجب عليك القيادة بجانبه مع التهدئة والانتباه لتجنب الاصطدام.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/markering_rechts_verticaal_3.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IA1', (SELECT id FROM categories WHERE code='M'), 'Type Ia1 - Bakens voor signalisatie op afstand, links', 'Type Ia1 - Distance guidance beacon, left', 'Type Ia1 - Balise de guidage à distance, gauche', 'النوع Ia1 - منارة توجيه المسافة، على اليسار', 'Type Ia1 - Bakens voor signalisatie op afstand, links', 'Type Ia1 - Distance guidance beacon, left', 'Type Ia1 - Balise de guidage à distance, gauche', 'النوع Ia1 - منارة توجيه المسافة، على اليسار', 'Dit bord wijst op een komende wijziging van de wegrichting naar links, en wordt gebruikt als vroegtijdige waarschuwing voor een gevaarlijke plek of bocht. Het helpt de bestuurder om zich vroeg voor te bereiden, het pad aan te passen en af te remmen, vooral bij bochten of tijdelijke omleidingen. U moet de richting van de schuine lijnen nauwkeurig volgen voor een veilige doorgang.', 'This traffic sign indicates an upcoming change in road direction to the left, and is used as an advance warning before a dangerous location or curve. It helps the driver prepare early, adjust the path, and slow down, especially at curves or temporary diversions. You must follow the direction of the diagonal lines precisely for safe passage.', 'Ce panneau de signalisation indique un changement imminent de direction de la route vers la gauche, et est utilisé comme avertissement préalable avant un endroit dangereux ou un virage. Il aide le conducteur à se préparer tôt, à ajuster sa trajectoire et à ralentir, surtout dans les virages ou les déviations temporaires. Vous devez suivre la direction des lignes diagonales avec précision pour un passage en toute sécurité.', 'تشير هذه العلامة المرورية إلى تغيير قادم في اتجاه الطريق إلى اليسار، وتستخدم كتحذير مسبق قبل موقع أو منحنى خطير. يساعد السائق على الاستعداد مبكراً وضبط المسار وإبطاء السرعة، خاصة عند المنعطفات أو التحويلات المؤقتة. يجب عليك اتباع اتجاه الخطوط القطرية بدقة من أجل المرور الآمن.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type Ia1 Bakens voor signalisatie op afstand, links.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IA2', (SELECT id FROM categories WHERE code='M'), 'Type Ia2 - Bakens voor signalisatie op afstand, splitsing links', 'Type Ia2 - Distance guidance beacon, split left', 'Type Ia2 - Balise de guidage à distance, bifurcation gauche', 'النوع Ia2 - منارة توجيه المسافة، منقسمة إلى اليسار', 'Type Ia2 - Bakens voor signalisatie op afstand, splitsing links', 'Type Ia2 - Distance guidance beacon, split left', 'Type Ia2 - Balise de guidage à distance, bifurcation gauche', 'النوع Ia2 - منارة توجيه المسافة، منقسمة إلى اليسار', 'Dit bord wijst op een splitsing of wijziging in het wegverloop naar links, en wordt gebruikt als vroegtijdige waarschuwing voor de splitsingsplek of omleiding. Het helpt de bestuurder om op tijd de juiste richting te kiezen, waarbij het noodzakelijk is om af te remmen en de richting van de pijl te volgen om te voorkomen dat u een verkeerde of gevaarlijke weg inslaat.', 'This traffic sign indicates a split or change in the road path heading to the left, and is used as an advance warning before the split location or diversion. It helps the driver choose the correct path at the right time, with the need to slow down and follow the arrow direction to avoid entering a wrong or dangerous path.', 'Ce panneau de signalisation indique une bifurcation ou un changement de trajectoire de la route vers la gauche, et est utilisé comme avertissement préalable avant l''emplacement de la bifurcation ou la déviation. Il aide le conducteur à choisir le bon chemin au bon moment, avec la nécessité de ralentir et de suivre la direction de la flèche pour éviter d''emprunter un chemin erroné ou dangereux.', 'تشير هذه العلامة المرورية إلى انقسام أو تغيير مسار الطريق المتجه إلى اليسار، وتستخدم كتحذير مسبق قبل موقع الانقسام أو التحويل. يساعد السائق على اختيار المسار الصحيح في الوقت المناسب، مع ضرورة التخفيف من السرعة واتباع اتجاه السهم لتجنب الدخول في مسار خاطئ أو خطير.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type Ia2 Bakens voor signalisatie op afstand, splitsing links.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IB1', (SELECT id FROM categories WHERE code='M'), 'Type Ib1 - Bakens voor signalisatie op afstand, rechts', 'Type Ib1 - Distance guidance beacon, right', 'Type Ib1 - Balise de guidage à distance, droite', 'النوع Ib1 - منارة توجيه المسافة، على اليمين', 'Type Ib1 - Bakens voor signalisatie op afstand, rechts', 'Type Ib1 - Distance guidance beacon, right', 'Type Ib1 - Balise de guidage à distance, droite', 'النوع Ib1 - منارة توجيه المسافة، على اليمين', 'Dit bord wijst op een komende wijziging van de wegrichting naar rechts, en wordt gebruikt als vroegtijdige waarschuwing voor een gevaarlijke plek of bocht. Het helpt de bestuurder om zich vroeg voor te bereiden, het pad aan te passen en af te remmen, vooral bij bochten of tijdelijke omleidingen. U moet de richting van de schuine lijnen nauwkeurig volgen voor een veilige doorgang.', 'This traffic sign indicates an upcoming change in road direction to the right, and is used as an advance warning before a dangerous location or curve. It helps the driver prepare early, adjust the path, and slow down, especially at curves or temporary diversions. You must follow the direction of the diagonal lines precisely for safe passage.', 'Ce panneau de signalisation indique un changement imminent de direction de la route vers la droite, et est utilisé comme avertissement préalable avant un endroit dangereux ou un virage. Il aide le conducteur à se préparer tôt, à ajuster sa trajectoire et à ralentir, surtout dans les virages ou les déviations temporaires. Vous devez suivre la direction des lignes diagonales avec précision pour un passage en toute sécurité.', 'تشير هذه العلامة المرورية إلى تغيير قادم في اتجاه الطريق إلى اليمين، وتستخدم كتحذير مسبق قبل موقع أو منحنى خطير. يساعد السائق على الاستعداد مبكراً وضبط المسار وإبطاء السرعة، خاصة عند المنعطفات أو التحويلات المؤقتة. يجب عليك اتباع اتجاه الخطوط القطرية بدقة من أجل المرور الآمن.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type Ib1 Bakens voor signalisatie op afstand, rechts.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IB2', (SELECT id FROM categories WHERE code='M'), 'Type Ib2 - Bakens voor signalisatie op afstand, splitsing rechts', 'Type Ib2 - Distance guidance beacon, split right', 'Type Ib2 - Balise de guidage à distance, bifurcation droite', 'النوع Ib2 - منارة توجيه المسافة، منقسمة إلى اليمين', 'Type Ib2 - Bakens voor signalisatie op afstand, splitsing rechts', 'Type Ib2 - Distance guidance beacon, split right', 'Type Ib2 - Balise de guidage à distance, bifurcation droite', 'النوع Ib2 - منارة توجيه المسافة، منقسمة إلى اليمين', 'Dit bord wijst op een splitsing of wijziging in het wegverloop naar rechts, en wordt gebruikt als vroegtijdige waarschuwing voor de splitsingsplek of omleiding. Het helpt de bestuurder om op tijd de juiste richting te kiezen, waarbij het noodzakelijk is om af te remmen, op te letten en de richting van de pijl te volgen om te voorkomen dat u een verkeerde of onveilige weg inslaat.', 'This traffic sign indicates a split or change in the road path heading to the right, and is used as an advance warning before the split location or diversion. It helps the driver choose the correct path at the right time, with the need to slow down, pay attention, and follow the arrow direction to avoid entering a wrong or unsafe path.', 'Ce panneau de signalisation indique une bifurcation ou un changement de trajectoire de la route vers la droite, et est utilisé comme avertissement préalable avant l''emplacement de la bifurcation ou la déviation. Il aide le conducteur à choisir le bon chemin au bon moment, avec la nécessité de ralentir, faire attention et suivre la direction de la flèche pour éviter d''emprunter un chemin erroné ou dangereux.', 'تشير هذه العلامة المرورية إلى انقسام أو تغيير في مسار الطريق المتجه إلى اليمين، وتستخدم كتحذير مسبق قبل موقع الانقسام أو التحويل. يساعد السائق على اختيار المسار الصحيح في الوقت المناسب، مع ضرورة التهدئة والانتباه واتباع اتجاه السهم لتجنب الدخول في مسار خاطئ أو غير آمن.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type Ib2 Bakens voor signalisatie op afstand, splitsing rechts.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('TYPE-IIB', (SELECT id FROM categories WHERE code='M'), 'Type IIb - Baken voor zijdelingse signalisatie, rechts', 'Type IIb - Lateral signalization beacon, right', 'Type IIb - Balise de signalisation latérale, droite', 'النوع IIb - منارة الإشارة الجانبية، على اليمين', 'Type IIb - Baken voor zijdelingse signalisatie, rechts', 'Type IIb - Lateral signalization beacon, right', 'Type IIb - Balise de signalisation latérale, droite', 'النوع IIb - منارة الإشارة الجانبية، على اليمين', 'Dit bord wijst op een obstakel of versmalling aan de zijkant van de weg, en de bestuurder moet aan de rechterkant passeren volgens de richting van de schuine lijnen. Het wordt vaak gebruikt bij wegwerkzaamheden of vaste obstakels, en u moet afremmen en de aangegeven richting nauwkeurig volgen om een botsing te voorkomen.', 'This traffic sign indicates an obstacle or narrowing on the side of the road, and the driver must pass on the right side according to the direction of the diagonal lines. It is often used at roadworks or fixed barriers, and you must slow down and follow the indicated direction precisely to avoid a collision.', 'Ce panneau de signalisation indique un obstacle ou un rétrécissement sur le côté de la route, et le conducteur doit passer du côté droit selon la direction des lignes diagonales. Il est souvent utilisé lors de travaux routiers ou d''obstacles fixes, et vous devez ralentir et suivre la direction indiquée avec précision pour éviter une collision.', 'تشير هذه العلامة المرورية إلى وجود عائق أو تضييق على جانب الطريق، ويجب على السائق المرور على الجانب الأيمن حسب اتجاه الخطوط القطرية. يتم استخدامه غالبًا في أعمال الطرق أو الحواجز الثابتة، ويجب عليك إبطاء السرعة واتباع الاتجاه المشار إليه بدقة لتجنب الاصطدام.', '/api/traffic-signs/image/assets/signs/afbakeningsborden/Type IIb Baken voor zijdelingse signalisatie, rechts.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F39', (SELECT id FROM categories WHERE code='H'), 'Aankondiging van een omleiding', 'Diversion announcement', 'Annonce de déviation', 'إعلان تحويلة طريق', 'Aankondiging van een omleiding', 'Diversion announcement', 'Annonce de déviation', 'إعلان تحويلة طريق', 'Dit verkeersbord geeft aan dat er een tijdelijke omleiding is die verplicht moet worden gevolgd vanwege wegwerkzaamheden of een obstakel op de weg. De pijl geeft de richting van de omleiding aan. De tekst kan een uitzondering vermelden voor bepaalde voertuigen zoals openbaar vervoer of zware voertuigen. Alle andere bestuurders moeten de omleiding volgen tot de werkzaamheden zijn afgerond of een andere aanwijzing wordt gegeven.', 'This traffic sign indicates a temporary diversion that must be followed due to roadworks or an obstacle on the road. The arrow indicates the direction of the diversion. The text may indicate an exception for certain vehicles such as public transport or heavy vehicles. All other drivers must follow the diversion until the works are completed or another instruction is given.', 'Ce panneau de signalisation indique une déviation temporaire qui doit être suivie obligatoirement en raison de travaux ou d''un obstacle sur la route. La flèche indique la direction de la déviation. Le texte peut indiquer une exception pour certains véhicules comme les transports en commun ou les poids lourds. Tous les autres conducteurs doivent suivre la déviation jusqu''à la fin des travaux ou jusqu''à ce qu''une autre instruction soit donnée.', 'تشير هذه العلامة المرورية إلى وجود تحويلة مؤقتة يجب اتباعها بسبب أعمال الطرق أو وجود عائق على الطريق. السهم يشير إلى اتجاه التحويل. وقد يشير النص إلى استثناء لمركبات معينة مثل وسائل النقل العام أو المركبات الثقيلة. يجب على جميع السائقين الآخرين اتباع التحويل حتى اكتمال الأعمال أو إعطاء تعليمات أخرى.', '/api/traffic-signs/image/signs/information_signs/F39 Aankondiging van een omleiding.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F79-V1', (SELECT id FROM categories WHERE code='H'), 'Tijdelijke verdeling van de rijstroken (met afstandsaanduiding)', 'Temporary lane reduction (with distance indication)', 'Réduction temporaire des voies (avec indication de distance)', 'تقليص عدد المسارات المؤدية إلى الأمام (من اليمين)', 'Tijdelijke verdeling van de rijstroken (met afstandsaanduiding)', 'Temporary lane reduction (with distance indication)', 'Réduction temporaire des voies (avec indication de distance)', 'تقليص عدد المسارات المؤدية إلى الأمام (من اليمين)', 'Dit tijdelijke verkeersbord (oranje) geeft aan dat de rechterrijstrook na 1500 meter zal eindigen. Bestuurders moeten geleidelijk naar de linkse rijstroken invoegen. Dit bord wordt gebruikt bij wegwerkzaamheden of tijdelijke verkeersmaatregelen om de verkeersstroom veilig te reguleren.', 'This temporary traffic sign (orange) indicates that the right lane will end after 1500 meters. Drivers must gradually merge into the left lanes. This sign is used during roadworks or temporary traffic measures to safely regulate traffic flow.', 'Ce panneau de signalisation temporaire (orange) indique que la voie de droite se terminera après 1500 mètres. Les conducteurs doivent progressivement se rabattre sur les voies de gauche. Ce panneau est utilisé lors de travaux routiers ou de mesures de circulation temporaires pour réguler le flux de circulation en toute sécurité.', 'تشير هذه الإشارة المؤقتة (برتقالية) إلى أن المسار الأيمن سينتهي بعد 1500 متر. يجب على السائقين الاندماج تدريجياً في الممرات اليسرى. تُستخدم هذه العلامة أثناء أعمال الطرق أو إجراءات المرور المؤقتة لتنظيم تدفق حركة المرور بأمان.', '/api/traffic-signs/image/assets/signs/Informatieborden_en_tijdelijke_verkeersmaatregelen/F79 Tijdelijke verdeling van de rijstroken (met afstandsaanduiding).png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F79', (SELECT id FROM categories WHERE code='H'), 'Tijdelijke verdeling van de rijstroken', 'End of obstacle or reserved lane (after 1500 meters)', 'Fin d''obstacle ou voie réservée (après 1500 mètres)', 'نهاية العائق أو المسار المحجوز (بعد 1500 متر)', 'Tijdelijke verdeling van de rijstroken', 'End of obstacle or reserved lane (after 1500 meters)', 'Fin d''obstacle ou voie réservée (après 1500 mètres)', 'نهاية العائق أو المسار المحجوز (بعد 1500 متر)', 'Dit tijdelijke verkeersbord geeft aan dat de gereserveerde rijstrook aan de linkerkant van de weg na 1500 meter weer beschikbaar wordt voor gebruik. Dit bord wordt gebruikt om aan te geven dat de weg wordt verbreed.', 'This temporary traffic sign indicates that the reserved lane on the left side of the road will become available again after 1500 meters. This sign is used to indicate road widening.', 'Ce panneau de signalisation temporaire indique que la voie réservée sur le côté gauche de la route redeviendra disponible après 1500 mètres. Ce panneau est utilisé pour indiquer l''élargissement de la route.', 'تشير هذه العلامة المرورية المؤقتة إلى أن المسار المحجوز على الجانب الأيسر من الطريق سوف يصبح متاحاً مرة أخرى بعد 1500 متر. تستخدم هذه العلامة للإشارة إلى توسيع الطريق.', '/api/traffic-signs/image/signs/information_signs/F79 Tijdelijke verdeling van de rijstroken (met afstandsaanduiding).png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F83', (SELECT id FROM categories WHERE code='H'), 'Versmalling van de rijbaan', 'End of obstacle and lane reopening', 'Fin d''obstacle et réouverture de voie', 'نهاية العائق وعودة المسار المحجوز للاستخدام', 'Versmalling van de rijbaan', 'End of obstacle and lane reopening', 'Fin d''obstacle et réouverture de voie', 'نهاية العائق وعودة المسار المحجوز للاستخدام', 'Dit tijdelijke verkeersbord geeft aan dat het tijdelijke obstakel op de weg (zoals barrières of wegwerkzaamheden) zal eindigen en de afgesloten rijstrook na 1500 meter weer wordt geopend. Dit bord markeert het einde van een verboden of afgesloten zone.', 'This temporary traffic sign indicates that the temporary obstacle on the road (such as barriers or roadworks) will end and the closed lane will reopen after 1500 meters. This sign marks the end of a prohibited or closed zone.', 'Ce panneau de signalisation temporaire indique que l''obstacle temporaire sur la route (comme les barrières ou les travaux) se terminera et que la voie fermée rouvrira après 1500 mètres. Ce panneau marque la fin d''une zone interdite ou fermée.', 'تشير هذه العلامة المرورية المؤقتة إلى أن العائق المؤقت على الطريق (مثل الحواجز أو أعمال الطرق) سينتهي وسيعاد فتح المسار المغلق بعد 1500 متر. تشير هذه العلامة إلى نهاية المنطقة المحظورة أو المغلقة.', '/api/traffic-signs/image/signs/information_signs/F83 Versmalling van de rijbaan.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F85', (SELECT id FROM categories WHERE code='H'), 'Verlegging van de rijbaan', 'Lane reduction (from left)', 'Réduction des voies (depuis la gauche)', 'تقليص عدد المسارات المؤدية إلى الأمام (من اليسار)', 'Verlegging van de rijbaan', 'Lane reduction (from left)', 'Réduction des voies (depuis la gauche)', 'تقليص عدد المسارات المؤدية إلى الأمام (من اليسار)', 'Dit tijdelijke verkeersbord waarschuwt dat de linkerrijstrook na een bepaalde afstand (1500 meter) zal verdwijnen. Bestuurders in deze rijstrook moeten naar rechts overgaan. Dit bord wordt gebruikt in tijdelijke werkzones om het verkeer veilig te begeleiden.', 'This temporary traffic sign warns that the left lane will disappear after a certain distance (1500 meters). Drivers in this lane must move to the right. This sign is used in temporary work zones to safely guide traffic.', 'Ce panneau de signalisation temporaire avertit que la voie de gauche disparaîtra après une certaine distance (1500 mètres). Les conducteurs sur cette voie doivent se déplacer vers la droite. Ce panneau est utilisé dans les zones de travaux temporaires pour guider le trafic en toute sécurité.', 'تحذر هذه العلامة المرورية المؤقتة من أن المسار الأيسر سوف يختفي بعد مسافة معينة (1500 متر). يجب على السائقين في هذا المسار التحرك إلى اليمين. تُستخدم هذه العلامة في مناطق العمل المؤقتة لتوجيه حركة المرور بشكل آمن.', '/api/traffic-signs/image/signs/information_signs/F85 Verlegging van de rijbaan.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F89', (SELECT id FROM categories WHERE code='H'), 'Aanduiding van de maximumsnelheid per rijstrook', 'Speed limit per lane with distance indication', 'Vitesse maximale par voie avec indication de distance', 'الحد الأقصى للسرعة لكل حارة مع إشارة المسافة', 'Aanduiding van de maximumsnelheid per rijstrook', 'Speed limit per lane with distance indication', 'Vitesse maximale par voie avec indication de distance', 'الحد الأقصى للسرعة لكل حارة مع إشارة المسافة', 'Dit verkeersbord heeft hetzelfde doel als F91, maar wordt gebruikt om bestuurders vooraf te waarschuwen dat de verschillende snelheden per rijstrook na 1500 meter van toepassing zullen zijn. Het geeft tijd om van rijstrook te wisselen indien nodig.', 'This traffic sign has the same purpose as F91, but is used to warn drivers in advance that the different speeds per lane will apply after 1500 meters. It gives time to change lanes if needed.', 'Ce panneau de signalisation a le même objectif que F91, mais est utilisé pour avertir les conducteurs à l''avance que les différentes vitesses par voie s''appliqueront après 1500 mètres. Il donne le temps de changer de voie si nécessaire.', 'هذه العلامة المرورية لها نفس غرض F91، ولكنها تستخدم لتحذير السائقين مسبقًا من أن السرعات المختلفة لكل حارة سيتم تطبيقها بعد 1500 متر. أنه يعطي الوقت لتغيير الممرات إذا لزم الأمر.', '/api/traffic-signs/image/signs/information_signs/F89 Aanduiding van de maximumsnelheid per rijstrook.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F91', (SELECT id FROM categories WHERE code='H'), 'Aanduiding van de maximumsnelheid per rijstrook (zonder afstand)', 'Maximum speed per lane indication', 'Indication de vitesse maximale par voie', 'تحديد السرعة القصوى حسب المسارات', 'Aanduiding van de maximumsnelheid per rijstrook (zonder afstand)', 'Maximum speed per lane indication', 'Indication de vitesse maximale par voie', 'تحديد السرعة القصوى حسب المسارات', 'Dit verkeersbord geeft de maximumsnelheid per rijstrook aan, bijvoorbeeld de linkerrijstrook 70 km/u, de middelste 90 km/u, enzovoort. Dit bord wordt gebruikt op snelwegen met meerdere rijstroken om de verkeersstroom te reguleren.', 'This traffic sign indicates the maximum speed in each lane of the road, for example the left lane 70 km/h, the middle 90 km/h, and so on. It is used on multi-lane highways to regulate traffic flow.', 'Ce panneau de signalisation indique la vitesse maximale dans chaque voie de la route, par exemple la voie de gauche 70 km/h, celle du milieu 90 km/h, et ainsi de suite. Il est utilisé sur les autoroutes à plusieurs voies pour réguler le flux de circulation.', 'تشير هذه العلامة المرورية إلى السرعة القصوى في كل حارة من الطريق، مثلاً الحارة اليسرى 70 كم/ساعة، الوسطى 90 كم/ساعة وهكذا. يتم استخدامه على الطرق السريعة متعددة المسارات لتنظيم تدفق حركة المرور.', '/api/traffic-signs/image/signs/information_signs/F91 Aanduiding van de maximumsnelheid per rijstrook (zonder afstand).png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F95', (SELECT id FROM categories WHERE code='H'), 'Einde van een rijstrook', 'Exit to service station or rest area', 'Sortie vers station-service ou aire de repos', 'مخرج إلى محطة خدمات أو استراحة', 'Einde van een rijstrook', 'Exit to service station or rest area', 'Sortie vers station-service ou aire de repos', 'مخرج إلى محطة خدمات أو استراحة', 'Dit verkeersbord geeft aan dat er een afrit is naar een servicegebied langs de snelweg, zoals een tankstation of rustplaats. De zijlijn toont de richting van de afrit naar de zijweg.', 'This traffic sign indicates an exit leading to a service area on the highway, such as a gas station or rest area. The side line shows the direction of the deviation towards the side road.', 'Ce panneau de signalisation indique une sortie menant à une zone de services sur l''autoroute, comme une station-service ou une aire de repos. La ligne latérale montre la direction de la déviation vers la voie latérale.', 'تشير هذه العلامة المرورية إلى مخرج يؤدي إلى منطقة خدمة على الطريق السريع، مثل محطة وقود أو منطقة استراحة. يوضح الخط الجانبي اتجاه الانحراف نحو الطريق الجانبي.', '/api/traffic-signs/image/signs/information_signs/F95 Einde van een rijstrook.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

INSERT INTO traffic_signs (sign_code, category_id, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES ('F98', (SELECT id FROM categories WHERE code='H'), 'Bijzondere rijstrookregeling', 'Emergency lane sign on highway', 'Panneau de voie d''urgence sur autoroute', 'علامة حارة الطوارئ على الطريق السريع', 'Bijzondere rijstrookregeling', 'Emergency lane sign on highway', 'Panneau de voie d''urgence sur autoroute', 'علامة حارة الطوارئ على الطريق السريع', 'Dit verkeersbord wijst de bestuurder naar een speciale noodstrook aan de zijkant van de snelweg, bedoeld voor noodgevallen zoals een mechanisch defect of om hulp te vragen. Alleen te gebruiken in noodsituaties.', 'This traffic sign directs the driver to a designated emergency area on the side of the highway, for example for stopping in case of mechanical breakdown or requesting assistance. Only to be used in emergency situations.', 'Ce panneau de signalisation dirige le conducteur vers une zone d''urgence désignée sur le côté de l''autoroute, par exemple pour s''arrêter en cas de panne mécanique ou pour demander de l''aide. À utiliser uniquement en cas d''urgence.', 'تقوم هذه العلامة المرورية بتوجيه السائق إلى منطقة طوارئ مخصصة على جانب الطريق السريع، مثلاً للتوقف في حالة حدوث عطل ميكانيكي أو طلب المساعدة. يستخدم فقط في حالات الطوارئ.', '/api/traffic-signs/image/signs/information_signs/F98 Bijzondere rijstrookregeling.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar), description_nl=VALUES(description_nl), description_en=VALUES(description_en), description_fr=VALUES(description_fr), description_ar=VALUES(description_ar), long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en), long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar), image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

